contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint collectAmount, uint unlockTime) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        require(collectAmount <= amount);
        require(unlockTime <= block.timestamp);

        c.Put{value: amount}(unlockTime);
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint cBalBefore = address(c).balance;

        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlock, uint afterBal) = c.Acc(address(this));

        assert(
            (beforeBal + amount >= c.MinSum() && collectAmount > 0 && !reverted)
                ? (afterBal == beforeBal + amount - collectAmount && address(c).balance == cBalBefore - collectAmount)
                : (reverted || (afterBal == beforeBal + amount && address(c).balance == cBalBefore))
        );
    }

    receive() external payable {}
}

